import{_ as n,o as r,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Gesetz gegen Wettbewerbsbeschränkungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/47-反垄断法.md","filePath":"de/47-反垄断法.md","lastUpdated":1789183869000}'),s={name:"de/47-反垄断法.md"};function u(d,e,a,o,l,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="gesetz-gegen-wettbewerbsbeschrankungen" tabindex="-1">Gesetz gegen Wettbewerbsbeschränkungen <a class="header-anchor" href="#gesetz-gegen-wettbewerbsbeschrankungen" aria-label="Permalink to &quot;Gesetz gegen Wettbewerbsbeschränkungen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>47</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Wettbewerbsverbot, Anti-Räuber, Markt Wettbewerb, Ressourcenmonopol, Kultivierungsmonopol</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Gesetz gegen Wettbewerbsbeschränkungen》 ist eines der fünf ergänzenden Gesetze der Anker-Symbiose-Zivilisation. Es zielt darauf ab, monopolistische Praktiken zu verhindern und zu unterbinden, den fairen Wettbewerb auf dem Markt zu schützen, die Effizienz der Wirtschaftsoperation zu verbessern, die Verbraucherinteressen und das gesellschaftliche Gemeinwohl zu wahren und die gesunde Entwicklung der Symbiose-Wirtschaft zu fördern. In der Anker-Symbiose-Zivilisation richtet sich das Wettbewerbsverbot nicht nur gegen Monopole im traditionellen Wirtschaftsbereich, sondern auch gegen Sonderformen wie Kultivierungsressourcenmonopol, Wissensmonopol und Ebenenmonopol.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip des fairen Wettbewerbs</td><td>Aufrechterhaltung der Marktordnung des fairen Wettbewerbs, Verbot monopolistischer Praktiken, die den Wettbewerb ausschließen oder beschränken</td></tr><tr><td>Prinzip der Anti-Räuberei</td><td>Der Kern des Wettbewerbsverbots ist die Anti-Räuberei, die verhindert, dass Monopolisten durch ihre monopolistische Stellung die Interessen aller Wesen ausbeuten</td></tr><tr><td>Prinzip der Ressourcenöffnung</td><td>Öffentliche Kultivierungsressourcen und Grundwissen müssen für die gesamte Gesellschaft offen sein, und privates Monopol ist verboten</td></tr><tr><td>Prinzip des Gleichgewichts von Effizienz und Gerechtigkeit</td><td>Das Wettbewerbsverbot muss sowohl die Wettbewerbseffizienz schützen als auch die Ressourcenverschwendung durch übermäßige Streuung verhindern</td></tr><tr><td>Prinzip der inter-ebenen Anwendbarkeit</td><td>Das Wettbewerbsgesetz gilt für alle Ebenen und Märkte innerhalb von Hengyuanzhou, und inter-ebenen Monopole werden ebenfalls reguliert</td></tr></tbody></table><h2 id="ii-arten-monopolistischer-praktiken" tabindex="-1">II. Arten monopolistischer Praktiken <a class="header-anchor" href="#ii-arten-monopolistischer-praktiken" aria-label="Permalink to &quot;II. Arten monopolistischer Praktiken&quot;">​</a></h2><p>Die durch dieses Gesetz regulierten monopolistischen Praktiken umfassen folgende vier Arten:</p><h3 id="_1-monopolvereinbarungen" tabindex="-1">(1) Monopolvereinbarungen <a class="header-anchor" href="#_1-monopolvereinbarungen" aria-label="Permalink to &quot;(1) Monopolvereinbarungen&quot;">​</a></h3><p>Monopolvereinbarungen beziehen sich auf Vereinbarungen, Beschlüsse oder andere abgestimmte Verhaltensweisen, die den Wettbewerb ausschließen oder beschränken, einschließlich:</p><ol><li><strong>Horizontale Monopolvereinbarungen</strong>: Vereinbarungen zwischen konkurrierenden Unternehmern über Preisbindung, Produktionsbeschränkung, Marktaufteilung, gemeinsamen Handelshandel, usw.</li><li><strong>Vertikale Monopolvereinbarungen</strong>: Vereinbarungen zwischen Unternehmern und Handelspartnern über Festlegung der Weiterverkaufspreise, Begrenzung der Mindestweiterverkaufspreise, usw.</li><li><strong>Monopolvereinbarungen über Kultivierungsressourcen</strong>: Vereinbarungen zwischen Kultivierungssekten über die Aufteilung von Kultivierungsressourcenregionen, Vereinheitlichung der Ressourcenpreise, Begrenzung der Ressourcenversorgung, usw.</li><li><strong>Wissensmonopolvereinbarungen</strong>: Vereinbarungen zwischen Bildungseinrichtungen und Kultivierungssekten über die Blockierung von Kultivierungsmethoden, Begrenzung der Wissensverbreitung, Vereinheitlichung der Studiengebührenstandards, usw.</li></ol><h3 id="_2-missbrauch-der-marktbeherrschenden-stellung" tabindex="-1">(2) Missbrauch der marktbeherrschenden Stellung <a class="header-anchor" href="#_2-missbrauch-der-marktbeherrschenden-stellung" aria-label="Permalink to &quot;(2) Missbrauch der marktbeherrschenden Stellung&quot;">​</a></h3><p>Die marktbeherrschende Stellung bezieht sich auf die Marktstellung, in der ein Unternehmer in der Lage ist, Preise, Mengen oder andere Handelsbedingungen von Waren auf dem relevanten Markt zu kontrollieren, oder den Eintritt anderer Unternehmer in den relevanten Markt zu behindern oder zu beeinflussen. Praktiken des Missbrauchs der marktbeherrschenden Stellung umfassen:</p><table tabindex="0"><thead><tr><th>Art der Praxis</th><th>Spezifische Manifestation</th></tr></thead><tbody><tr><td>Unfaire Preisgestaltung</td><td>Verkauf von Waren zu unfair hohen Preisen oder Kauf von Waren zu unfair niedrigen Preisen</td></tr><tr><td>Räuberische Preisgestaltung</td><td>Ohne berechtigten Grund Verkauf von Waren zu Preisen unterhalb der Kosten, um Wettbewerber auszuschalten</td></tr><tr><td>Handelsverweigerung</td><td>Ohne berechtigten Grund Verweigerung des Handels mit dem Handelspartner</td></tr><tr><td>Handelsbeschränkung</td><td>Ohne berechtigten Grund Beschränkung des Handelspartners, nur mit ihm selbst zu handeln</td></tr><tr><td>Bündelverkauf</td><td>Ohne berechtigten Grund Bündelverkauf von Waren oder Auferlegung anderer unzumutbarer Bedingungen beim Handel</td></tr><tr><td>Diskriminierende Behandlung</td><td>Ohne berechtigten Grund diskriminierende Behandlung in Bezug auf Handelsbedingungen wie Preise gegenüber Handelspartnern mit gleichen Bedingungen</td></tr><tr><td>Blockierung von Kultivierungsressourcen</td><td>Nutzung der monopolistischen Stellung von Kultivierungsressourcen, um Wettbewerbern oder Verbrauchern die Bereitstellung notwendiger Ressourcen zu verweigern</td></tr><tr><td>Wissensblockierung</td><td>Nutzung der monopolistischen Stellung des Wissens, um grundlegende Kultivierungsmethoden zu blockieren und Lernende zur Zahlung hoher Gebühren zu zwingen</td></tr></tbody></table><h3 id="_3-unternehmenskonzentration" tabindex="-1">(3) Unternehmenskonzentration <a class="header-anchor" href="#_3-unternehmenskonzentration" aria-label="Permalink to &quot;(3) Unternehmenskonzentration&quot;">​</a></h3><p>Unternehmenskonzentration bezieht sich auf folgende Situationen: Fusion von Unternehmen; Erwerb der Kontrolle über andere Unternehmen durch Erwerb von Aktien oder Vermögenswerten; Erwerb der Kontrolle über andere Unternehmen oder die Fähigkeit, entscheidenden Einfluss auf andere Unternehmen auszuüben, durch Verträge usw.</p><p>Eine Unternehmenskonzentration, die die Anmeldeschwelle erreicht, muss vorab bei der Wettbewerbsbehörde angemeldet werden, und eine nicht angemeldete darf nicht durchgeführt werden. Bei der Prüfung der Unternehmenskonzentration durch die Wettbewerbsbehörde sind folgende Faktoren zu berücksichtigen:</p><ol><li>Der Marktanteil der an der Konzentration beteiligten Unternehmen auf dem relevanten Markt und ihre Marktmacht.</li><li>Die Marktkonzentration des relevanten Marktes.</li><li>Die Auswirkungen der Unternehmenskonzentration auf Markteintritt und technologischen Fortschritt.</li><li>Die Auswirkungen der Unternehmenskonzentration auf Verbraucher und andere relevante Unternehmen.</li><li>Die Auswirkungen der Unternehmenskonzentration auf die Öffnung von Kultivierungsressourcen und die Wissensverbreitung.</li><li>Die Auswirkungen der Unternehmenskonzentration auf die Entwicklung der Volkswirtschaft und den gemeinsamen Fortschritt aller Rassen.</li></ol><h3 id="_4-missbrauch-administrativer-befugnisse-zum-ausschluss-oder-zur-beschrankung-des-wettbewerbs" tabindex="-1">(4) Missbrauch administrativer Befugnisse zum Ausschluss oder zur Beschränkung des Wettbewerbs <a class="header-anchor" href="#_4-missbrauch-administrativer-befugnisse-zum-ausschluss-oder-zur-beschrankung-des-wettbewerbs" aria-label="Permalink to &quot;(4) Missbrauch administrativer Befugnisse zum Ausschluss oder zur Beschränkung des Wettbewerbs&quot;">​</a></h3><p>Verwaltungsbehörden und Organisationen, die durch Gesetze und Verordnungen zur Verwaltung öffentlicher Angelegenheiten ermächtigt sind, dürfen ihre administrativen Befugnisse nicht missbrauchen, um folgende Praktiken durchzuführen:</p><ol><li>Beschränkung oder verdeckte Beschränkung von Einheiten oder Einzelpersonen, Waren zu betreiben, zu kaufen oder zu verwenden, die von den von ihnen bestimmten Unternehmern bereitgestellt werden.</li><li>Behinderung des freien Warenverkehrs zwischen Regionen und zwischen Ebenen.</li><li>Ausschluss oder Beschränkung von Unternehmern aus anderen Regionen oder Ebenen von der Teilnahme an lokalen Ausschreibungen und Wettbewerben.</li><li>Ausschluss oder Beschränkung von Unternehmern aus anderen Regionen oder Ebenen von lokalen Investitionen oder der Errichtung von Zweigstellen.</li><li>Zwang von Unternehmern, die in diesem Gesetz vorgesehenen monopolistischen Praktiken durchzuführen.</li><li>Erlass von Vorschriften mit Inhalten, die den Wettbewerb ausschließen oder beschränken.</li></ol><h2 id="iii-besondere-wettbewerbsregeln-im-kultivierungsbereich" tabindex="-1">III. Besondere Wettbewerbsregeln im Kultivierungsbereich <a class="header-anchor" href="#iii-besondere-wettbewerbsregeln-im-kultivierungsbereich" aria-label="Permalink to &quot;III. Besondere Wettbewerbsregeln im Kultivierungsbereich&quot;">​</a></h2><p>Der Kultivierungsbereich ist ein Schwerpunktbereich des Wettbewerbsverbots in der Anker-Symbiose-Zivilisation, und dieses Gesetz sieht besondere Regeln vor:</p><ol><li><strong>Verpflichtung zur Öffnung der Grundmethoden</strong>: Die Grundmethoden der dreihundert Ursprungs-Kultivierungssysteme gehören zum öffentlichen Wissen, und keine Organisation oder Einzelperson darf sie monopolisieren, blockieren oder gegen Entgelt vermitteln.</li><li><strong>Gerechte Verteilung von Kultivierungsressourcen</strong>: Öffentliche Kultivierungsressourcen werden durch den Mechanismus des gemeinsamen Produktionsvertrags gerecht verteilt, und es ist verboten, dass Sekten oder Einzelpersonen hochwertige Kultivierungsressourcen monopolisieren.</li><li><strong>Verbot der Kultivierungsdiskriminierung</strong>: Kultivierungssekten dürfen bei der Zulassung und Vermittlung keine diskriminierenden Bedingungen aufgrund von Rasse, Herkunft, Kultivierungsniveau usw. festlegen.</li><li><strong>Verpflichtung zum Austausch von fortgeschrittenem Wissen</strong>: Kultivierer, die den Standard des höchsten Wesens der Ebene erreichen, sind verpflichtet, ihre Kultivierungserfahrungen und Forschungsergebnisse unter dem Schutz vernünftiger geistiger Eigentumsrechte mit der Gesellschaft zu teilen.</li><li><strong>Wettbewerbsverbot bei der Ebenenentwicklung</strong>: Das Entwicklungsrecht neuer Ebenen wird durch offenen Wettbewerb verteilt, und es ist verboten, dass wenige Mächte das Entwicklungsrecht der Ebenen monopolisieren.</li></ol><h2 id="iv-wettbewerbsbehorde" tabindex="-1">IV. Wettbewerbsbehörde <a class="header-anchor" href="#iv-wettbewerbsbehorde" aria-label="Permalink to &quot;IV. Wettbewerbsbehörde&quot;">​</a></h2><p>Der Staat errichtet eine Wettbewerbsbehörde, die für die Durchsetzung des Wettbewerbsverbots verantwortlich ist und folgende Aufgaben erfüllt:</p><ol><li>Erforschung und Ausarbeitung relevanter Wettbewerbspolitiken.</li><li>Organisation von Untersuchungen und Bewertungen der allgemeinen Wettbewerbssituation des Marktes und Veröffentlichung von Bewertungsberichten.</li><li>Erlass und Veröffentlichung von Wettbewerbsrichtlinien.</li><li>Koordinierung der administrativen Durchsetzungsarbeit des Wettbewerbsverbots.</li><li>Untersuchung und Ahndung von Fällen wie Monopolvereinbarungen, Missbrauch der marktbeherrschenden Stellung, rechtswidriger Durchführung von Unternehmenskonzentrationen usw.</li><li>Untersuchung und Ahndung von Praktiken des Missbrauchs administrativer Befugnisse zum Ausschluss oder zur Beschränkung des Wettbewerbs.</li></ol><p>Die Wettbewerbsbehörde übt ihre Befugnisse unabhängig nach Gesetz aus und unterliegt keiner Einmischung durch Verwaltungsbehörden, gesellschaftliche Organisationen und Einzelpersonen.</p><h2 id="v-rechtliche-verantwortung" tabindex="-1">V. Rechtliche Verantwortung <a class="header-anchor" href="#v-rechtliche-verantwortung" aria-label="Permalink to &quot;V. Rechtliche Verantwortung&quot;">​</a></h2><p>Handlungen, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ul><li>Abschluss und Durchführung von Monopolvereinbarungen, Anordnung zur Einstellung der rechtswidrigen Handlung, Einziehung der rechtswidrigen Erträge und Geldbuße von 1% bis 10% des Umsatzes des Vorjahres.</li><li>Missbrauch der marktbeherrschenden Stellung, Anordnung zur Einstellung der rechtswidrigen Handlung, Einziehung der rechtswidrigen Erträge und Geldbuße von 1% bis 10% des Umsatzes des Vorjahres.</li><li>Rechtswidrige Durchführung einer Unternehmenskonzentration, Anordnung zur Einstellung der Konzentration, fristgerechte Veräußerung von Aktien oder Vermögenswerten, fristgerechte Übertragung des Geschäfts und Geldbuße von bis zu 500.000 Yuan.</li><li>Missbrauch administrativer Befugnisse zum Ausschluss oder zur Beschränkung des Wettbewerbs, die übergeordnete Behörde ordnet die Korrektur an, und die direkt verantwortlichen leitenden Angestellten und anderen direkt verantwortlichen Personen werden nach Gesetz bestraft.</li><li>Monopolistische Praktiken, die anderen Schaden zufügen, übernehmen die zivilrechtliche Schadensersatzverantwortung nach Gesetz.</li><li>In schweren Fällen, die eine Straftat darstellen, wird die strafrechtliche Verantwortung nach Gesetz verfolgt.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Gesetz gegen Wettbewerbsbeschränkungen》 ist die rechtliche Waffe des Anti-Räuberismus der Anker-Symbiose-Zivilisation in den Wirtschafts- und Kultivierungsbereichen. Durch die Regulierung von Monopolvereinbarungen, Missbrauch der marktbeherrschenden Stellung, Unternehmenskonzentration und Verwaltungsmonopol, insbesondere durch die Festlegung besonderer Regeln für das Kultivierungsressourcenmonopol und das Wissensmonopol, gewährleistet es den Marktwettbewerb und die faire Öffnung der Kultivierungsressourcen, verhindert, dass Monopol zu einer neuen Form der Ausbeutung aller Wesen wird, und wahrt das institutionelle Umfeld des fairen Wettbewerbs für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>42-消费者保护法 (Verbraucherschutzgesetz)</li><li>18-修炼资源开放机制 (Mechanismus zur Öffnung von Kultivierungsressourcen)</li><li>04-反掠夺主义核心论纲 (Kernprogramm des Anti-Räuberismus)</li></ul>',35)])])}const c=n(s,[["render",u]]);export{b as __pageData,c as default};
